    val ACTIVE_CHANNELS: List<IptvChannel> = ALL_CHANNELS.filter { it.isActive }
    val INACTIVE_CHANNELS: List<IptvChannel> = ALL_CHANNELS.filter { !it.isActive }

    fun getChannelById(id: String): IptvChannel? {
        return ALL_CHANNELS.firstOrNull { it.id.equals(id, ignoreCase = true) }
    }

    fun searchChannels(query: String, category: String = "All", includeInactive: Boolean = false): List<IptvChannel> {
        val base = if (includeInactive) ALL_CHANNELS else ACTIVE_CHANNELS
        return base.filter { channel ->
            val matchesCat = category == "All" || channel.category.equals(category, ignoreCase = true)
            val matchesQuery = query.isBlank() || channel.name.contains(query, ignoreCase = true) || channel.id.contains(query, ignoreCase = true)
            matchesCat && matchesQuery
        }
    }
